import importlib.metadata,json,hashlib,dns.rdata,airflow,airflow.sdk
from pathlib import Path
assert importlib.metadata.version('dnspython')=='2.9.2'
assert airflow.__version__=='3.3.2'
base=Path('/opt/aat'); policy=json.loads((base/'constraints-policy.json').read_text()); upstream=(base/'constraints-3.12.txt').read_bytes(); assert hashlib.sha256(upstream).hexdigest()==policy['upstream_sha256']
dns.rdata.from_text('IN','WKS','10.0.0.1 udp 53')
try: dns.rdata.from_text('IN','WKS','10.0.0.1 udp 65536')
except Exception as e: print('WKS_BOUND_REJECTED',type(e).__name__)
else: raise AssertionError('out-of-range WKS accepted')
print('DNS_VERSION_AND_SDK_AND_UPSTREAM_PASS')
